import{_ as a,o as r,c as i,aO as o}from"./chunks/framework.BFrk9dwu.js";const l="/travel/erhai.jpg",e="/travel/dali/half-fengyangyi-1.jpg",n="/travel/dali/half-gucheng-1.jpg",s="/travel/dali/d1-erhai-1.jpg",d="/travel/dali/d1-xizhou-1.jpg",g="/travel/dali/d2-yudai-1.jpg",h="/travel/dali/d2-zhonghe-1.jpg",v=JSON.parse('{"title":"大理：古城、洱海与苍山","description":"大理两天半的行程：半天凤阳邑和大理古城，一天洱海西线骑行，一天感通索道上苍山、横穿玉带路、中和索道下","frontmatter":{"title":"大理：古城、洱海与苍山","date":"2026-11-17T18:40:00.000Z","description":"大理两天半的行程：半天凤阳邑和大理古城，一天洱海西线骑行，一天感通索道上苍山、横穿玉带路、中和索道下","categories":["life","travel"],"permalink":"/pages/22168a"},"headers":[],"relativePath":"life/travel/dali.md","filePath":"life/travel/dali.md"}'),c={name:"life/travel/dali.md"};function u(p,t,f,m,_,b){return r(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="大理-古城、洱海与苍山" tabindex="-1">大理：古城、洱海与苍山 <a class="header-anchor" href="#大理-古城、洱海与苍山" aria-label="Permalink to &quot;大理：古城、洱海与苍山&quot;">​</a></h1><div class="travel-hero"><img src="'+l+'" alt="洱海边的木屋：水面平静，远山连绵，天空铺着一大片云"></div><p>两天半刚好：半天给凤阳邑和古城，一天给洱海西线，一天给苍山。不赶，也不留遗憾。</p><h2 id="什么时候去" tabindex="-1">什么时候去 <a class="header-anchor" href="#什么时候去" aria-label="Permalink to &quot;什么时候去&quot;">​</a></h2><ul><li><strong>3–5 月、9–11 月</strong>：晴天多，风小，骑车和爬山都舒服。</li><li><strong>11 月–次年 3 月</strong>：风大、湿冷，但人少，海鸥多。</li><li><strong>6–8 月</strong>：雨季，下午常有阵雨，苍山容易起雾，行程要留余地。</li></ul><h2 id="怎么到" tabindex="-1">怎么到 <a class="header-anchor" href="#怎么到" aria-label="Permalink to &quot;怎么到&quot;">​</a></h2><ul><li>丽江坐高铁到大理约两小时；昆明过来也差不多两小时。</li><li>大理机场到古城约 30 公里，打车四十分钟。</li><li>古城到才村、龙龛只有五六公里，骑车二十分钟，不用特意住到湖边。</li></ul><h2 id="两天半怎么走" tabindex="-1">两天半怎么走 <a class="header-anchor" href="#两天半怎么走" aria-label="Permalink to &quot;两天半怎么走&quot;">​</a></h2><h3 id="行前半日-·-凤阳邑和大理古城" tabindex="-1">行前半日 · 凤阳邑和大理古城 <a class="header-anchor" href="#行前半日-·-凤阳邑和大理古城" aria-label="Permalink to &quot;行前半日 · 凤阳邑和大理古城&quot;">​</a></h3><p>下午到，先去<strong>凤阳邑</strong>。离古城五公里，茶马古道上的村子，石板路、土墙、老院子，走一圈很安静。《去有风的地方》里那个小院就在这儿，现在对外开放，进门按店里的规矩来——有的要预约，有的买杯咖啡就能坐。</p><figure class="travel-photo"><img src="'+e+'" alt="凤阳邑：蜿蜒上坡的石板路，两侧是夯土老墙和木门，墙头长着仙人掌"><figcaption>凤阳邑：茶马古道上的石板路，墙头都是仙人掌</figcaption></figure><p>傍晚回<strong>大理古城</strong>，人民路、复兴路、洋人街一路走，苍山门那边看日落。晚饭找家白族菜馆，酸辣鱼、乳扇点一份。</p><p><strong>晚上在人民路找家小酒馆</strong>，点一杯慢慢喝，听台上的人唱歌。不用挑最响的那家，巷子里安静的反倒舒服。</p><figure class="travel-photo"><img src="'+n+'" alt="大理古城人民路夜晚：小店透出暖光，路灯昏黄，游客慢慢走过"><figcaption>夜里的人民路，小酒馆一间挨着一间</figcaption></figure><h3 id="day-1-·-洱海西线骑行" tabindex="-1">Day 1 · 洱海西线骑行 <a class="header-anchor" href="#day-1-·-洱海西线骑行" aria-label="Permalink to &quot;Day 1 · 洱海西线骑行&quot;">​</a></h3><ul><li>从<strong>才村</strong>出发，沿<strong>洱海生态廊道</strong>往北：龙龛、下鸡邑、磻溪村的 S 弯，到<strong>喜洲</strong>二十公里左右。</li><li>早上想看日出，就先到<strong>龙龛码头</strong>，水杉和栈桥在逆光里最好看。</li><li>中午在喜洲逛<strong>四方街</strong>、严家大院，吃两个喜洲粑粑，一个甜的、一个咸的。</li><li>喜洲从正义门做大巴回城10块。</li></ul><p>廊道上没有机动车，只有自行车和散步的人，可以租自行车或者电动车。</p><div class="travel-grid"><figure><img src="'+s+'" alt="洱海生态廊道：骑行道贴湖延伸，远处苍山连绵，骑行者背影"><figcaption>廊道贴着湖走，一路都是苍山</figcaption></figure><figure><img src="'+d+'" alt="喜洲四方街：摊主在铁板上烤喜洲粑粑，冒着热气"><figcaption>喜洲四方街，粑粑得吃两个</figcaption></figure></div><h3 id="day-2-·-苍山-感通上-中和下" tabindex="-1">Day 2 · 苍山：感通上，中和下 <a class="header-anchor" href="#day-2-·-苍山-感通上-中和下" aria-label="Permalink to &quot;Day 2 · 苍山：感通上，中和下&quot;">​</a></h3><ul><li>上午坐<strong>感通索道</strong>上山，索道站出来就是<strong>玉带云游路</strong>的起点，清碧溪、珍珑棋局、苍山大峡谷。</li><li><strong>玉带路</strong>沿着苍山半山横穿，十一公里左右，路面平缓但一直有小起伏，走三四个小时，一路能俯瞰洱海和整座古城。</li><li>走到<strong>中和寺</strong>，坐<strong>中和索道</strong>下山，索道是露天的很不错，索道下来就是三月街，离古城很近。</li></ul><p>两条索道别搞反方向：<strong>感通上、中和下</strong>。反过来走也行，但感通那边收得早，末班时间出发前先查清楚。</p><div class="travel-grid"><figure><img src="'+g+'" alt="苍山玉带路：半山横切的步道，越过树梢俯瞰洱海和古城，云雾在下方流动"><figcaption>玉带路上，脚边就是云</figcaption></figure><figure><img src="'+h+'" alt="苍山中和索道的红色缆车，山下是古城屋顶和洱海"><figcaption>中和索道下山，窗外全是洱海</figcaption></figure></div><h2 id="住哪" tabindex="-1">住哪 <a class="header-anchor" href="#住哪" aria-label="Permalink to &quot;住哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>适合</th><th>说明</th></tr></thead><tbody><tr><td>大理古城</td><td>主要住这儿</td><td>两天半的行程都从城里出发，晚上酒吧也在城里，去才村骑车二十分钟</td></tr></tbody></table><h2 id="吃什么" tabindex="-1">吃什么 <a class="header-anchor" href="#吃什么" aria-label="Permalink to &quot;吃什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>吃的</th><th>说明</th></tr></thead><tbody><tr><td>酸辣鱼</td><td>本地做法偏酸辣，鱼要现杀</td></tr><tr><td>乳扇</td><td>烤到起泡，抹玫瑰酱，甜的</td></tr><tr><td>饵丝</td><td>早饭来一碗，比米线更厚实</td></tr><tr><td>舂鸡脚</td><td>本地做法，有甜有咸</td></tr><tr><td>喜洲粑粑</td><td>破酥的，甜咸各一个</td></tr><tr><td>生皮</td><td>当地特色，肠胃弱的别冒险</td></tr></tbody></table><h2 id="避坑" tabindex="-1">避坑 <a class="header-anchor" href="#避坑" aria-label="Permalink to &quot;避坑&quot;">​</a></h2><ul><li><strong>环海路上的&quot;天空之镜&quot;&quot;最美拍照点&quot;</strong>：多半是私人搭的镜子，拍照单独收费，去之前问清价格。</li><li><strong>电瓶车续航</strong>：西线来回四十公里左右，租车先问能跑多少公里，别拿一台半电的车去环整圈（整圈一百二十公里）。</li><li><strong>生态廊道禁机动车</strong>：别把车开进去，也别信&quot;能开进去&quot;的包车司机。</li><li><strong>客栈的&quot;洱海景观房&quot;</strong>：一定看实拍图，很多是隔了一条公路的远景。</li><li><strong>苍山</strong>：索道末班时间先查好；玉带路只走正经路线，别抄野路；一有雾就下撤，山上雾起来什么都看不见。</li><li><strong>凤阳邑的院子</strong>：多数要消费或门票，进去之前先问一句。</li></ul><h2 id="花费参考-淡季" tabindex="-1">花费参考 | 淡季 <a class="header-anchor" href="#花费参考-淡季" aria-label="Permalink to &quot;花费参考 | 淡季&quot;">​</a></h2><p>两天半不含大交通，人均 210元：住宿 70元 一晚，租电瓶车一天五六十，苍山两条索道按景区标价另算（可以在小红书上买便宜一点，但是需要提前三十分钟买），吃饭一天六七十。价格年年变，出门前自己再核一遍。</p><p><a href="/life/travel/">← 回旅游攻略</a></p>',31)])])}const x=a(c,[["render",u]]);export{v as __pageData,x as default};
